# requires: Seurat SeuratObject harmony Matrix jsonlite digest ggplot2 patchwork
script <- normalizePath(sub("^--file=","",grep("^--file=",commandArgs(FALSE),value=TRUE)[1])); root <- normalizePath(file.path(dirname(script),"..","..","..")); mod <- file.path(root,"skills","seurat-integrate")
source(file.path(root,"skills/_shared/scripts/module_kit.R")); source(file.path(root,"skills/_shared/scripts/handoff.R"))
scratch <- Sys.getenv("OMICSTAT_TEST_TMP","/scratch")
check <- function(ok,label) { if(!isTRUE(ok)) stop(paste("FAIL",label)); cat("PASS",label,"\n") }
run <- function(module,args) { entry <- file.path(root,"skills",module,"scripts",paste0("run_",gsub("-","_",module),".R")); log <- tempfile(tmpdir=scratch); status <- system2("Rscript",c(entry,shQuote(args)),stdout=log,stderr=log); if(status!=0) stop(paste(readLines(log),collapse="\n")); cat(paste(readLines(log),collapse="\n"),"\n") }
anchor <- file.path(root,"acceptance/data/harmony_pbmc_stim.RData")
check(digest::digest(file=anchor,algo="sha256")=="d85a18ce8ec9dcb4ac86c8e195ed53ff893c5952a7d6bf70035a17856c9dc0ef","locked pbmc_stim payload hash")
library(Matrix); load(anchor); mat <- cbind(pbmc.stim,pbmc.ctrl); saveRDS(mat,file.path(scratch,"stim_counts.rds")); md <- data.frame(cell=colnames(mat),sample=c(rep("STIM",ncol(pbmc.stim)),rep("CTRL",ncol(pbmc.ctrl)))); md$stim <- md$sample; write.csv(md,file.path(scratch,"stim_metadata.csv"),row.names=FALSE)
qc <- file.path(scratch,"stim_qc"); cluster <- file.path(scratch,"stim_cluster"); out <- file.path(scratch,"integrate_anchor")
# Vignette uses min.cells=5 without filtering cells. Explicit wide limits keep all cells.
run("seurat-qc",c("--input",file.path(scratch,"stim_counts.rds"),"--input-format","rds","--metadata",file.path(scratch,"stim_metadata.csv"),"--outdir",qc,"--organism","Homo_sapiens","--feature-type","symbol","--mito-pattern","^MT-","--missing-mito","zero","--min-cells","5","--create-min-features","0","--min-features","0","--max-features","1000000","--min-counts","0","--max-counts","1000000000","--max-mito","100"))
run("seurat-cluster",c("--from-run",qc,"--outdir",cluster,"--normalization","LogNormalize","--hvg-batch-col","stim","--n-hvg","2000","--n-pcs","20","--dims","20","--neighbors","20","--umap-neighbors","30","--resolution","0.5","--seed","42"))
base <- c("--from-run",cluster,"--method","RunHarmony","--batch-col","stim","--dims","20","--neighbors","20","--umap-neighbors","30","--resolution","0.5","--seed","42")
run("seurat-integrate",c(base,"--outdir",out))
x <- readRDS(file.path(out,"objects/seurat.rds")); y <- readRDS(file.path(cluster,"objects/seurat.rds"))
check(ncol(x)==2000L,"PRINTED harmony 2000 graph nodes")
check(nrow(x[["harmony"]])==2000L && ncol(x[["harmony"]])==20L,"native Harmony reduction shape")
set.seed(42); y <- harmony::RunHarmony(y,group.by.vars="stim",dims.use=1:20,verbose=FALSE)
check(isTRUE(all.equal(SeuratObject::Embeddings(x[["harmony"]]),SeuratObject::Embeddings(y[["harmony"]]),tolerance=1e-8)),"REPLAY official RunHarmony embeddings")
# Verify explicit loading projection switch against both direct native routes.
check(isTRUE(all.equal(SeuratObject::Loadings(x[["harmony"]]),SeuratObject::Loadings(y[["harmony"]]))),"project.dim TRUE native loadings")
no_projection <- file.path(scratch,"integrate_no_projection")
run("seurat-integrate",c(base,"--harmony-project-dim","FALSE","--outdir",no_projection))
w <- readRDS(file.path(no_projection,"objects/seurat.rds"))
v <- readRDS(file.path(cluster,"objects/seurat.rds")); set.seed(42)
v <- harmony::RunHarmony(v,group.by.vars="stim",dims.use=1:20,project.dim=FALSE,verbose=FALSE)
check(isTRUE(all.equal(SeuratObject::Loadings(w[["harmony"]]),SeuratObject::Loadings(v[["harmony"]]))) && nrow(SeuratObject::Loadings(w[["harmony"]]))==0L,"project.dim FALSE native loadings")
check(nrow(SeuratObject::Loadings(x[["harmony"]]))>0L,"project.dim changes loading output")
check(any(grepl("Resolved RunHarmony project.dim = FALSE",readLines(file.path(no_projection,"draft/methods_results.md")),fixed=TRUE)),"resolved project.dim Methods")
check(isTRUE(all.equal(SeuratObject::LayerData(x,assay="RNA",layer="counts"),mat[rownames(x),colnames(x)])),"raw counts retained")
cat("OBSERVED communities",length(unique(x$cluster)),"edges",(length(x@graphs$integrated_snn@x)-ncol(x))/2,"\n")
h <- read_handoff(out,expect=list(seurat="Seurat"),front_end_ecosystem="seurat"); check(isTRUE(h$state$seurat$integrated) && length(h$upstream_runs)==3L,"real QC-cluster-integration handoff chain")
# The second documented route also must run end to end.
layer <- file.path(scratch,"integrate_layers"); run("seurat-integrate",c(base[!seq_along(base) %in% c(3,4)],"--method","HarmonyIntegration","--outdir",layer))
z <- readRDS(file.path(layer,"objects/seurat.rds")); check(ncol(z)==2000L && "harmony" %in% names(z@reductions),"HarmonyIntegration layer route")
paths <- c("tables/harmony.csv","tables/batch_clusters.csv")
if(Sys.getenv("OMICSTAT_WRITE_GOLDEN")=="1") os_golden_write(mod,out,paths)
check(os_golden_check(mod,out)$status=="PASS","main result tables golden")

source(file.path(root,"skills/_shared/scripts/calls_check.R"))
check(check_calls(list.files(file.path(mod,"scripts"),pattern="[.]R$",full.names=TRUE),file.path(mod,"scripts/calls_registry.json"))$ok,"registered calls")
check(check_default_drift(file.path(mod,"scripts/calls_registry.json"))$ok,"locked defaults")
check(!file.exists(file.path(root,"Rplots.pdf")),"no device leak")
